INSERT INTO `notices`
(`id`, `created_at`, `updated_at`, `title`, `content`, `pinned`, `created_by`)
VALUES
  (1,  '2026-02-01 08:00:00.000000', '2026-02-01 08:00:00.000000', '欢迎使用校园互助平台',           '发布任务前请先完善个人资料，便于同学快速联系并确认身份。', b'1', 1),
  (2,  '2026-02-02 09:00:00.000000', '2026-02-02 09:00:00.000000', '文明互助提醒',           '任务沟通请保持礼貌，严禁发布虚假信息或恶意刷单内容。', b'1', 1),
  (3,  '2026-02-03 10:00:00.000000', '2026-02-03 10:00:00.000000', '失物招领专题周',              '丢失证件、钥匙、书包、电子设备时，请优先选择失物招领分类。', b'0', 1),
  (4,  '2026-02-04 11:00:00.000000', '2026-02-04 11:00:00.000000', '图书馆安静时段提醒',              '图书馆附近的学习辅导任务请尽量避免大声讨论和喧哗。', b'0', 1),
  (5,  '2026-02-05 12:00:00.000000', '2026-02-05 12:00:00.000000', '悬赏安全提示',             '建议在任务开始前确认悬赏金额，并在系统内完成确认与评价。', b'0', 1),
  (6,  '2026-02-06 13:00:00.000000', '2026-02-06 13:00:00.000000', '宿舍配送说明',             '大件物品配送请遵守宿舍访客管理规定，必要时提前联系宿管。', b'0', 1),
  (7,  '2026-02-07 14:00:00.000000', '2026-02-07 14:00:00.000000', '志愿互助榜单',            '高信用用户将进入月度校园互助榜单，平台会优先展示。', b'0', 1),
  (8,  '2026-02-08 15:00:00.000000', '2026-02-08 15:00:00.000000', '隐私保护提醒',            '请勿在任务中公开身份证号、完整宿舍门牌号等敏感信息。', b'0', 1),
  (9,  '2026-02-09 16:00:00.000000', '2026-02-09 16:00:00.000000', '打印店维护通知',         '考试周期间打印任务较多，若时间紧张请尽量提前发布。', b'0', 1),
  (10, '2026-02-10 17:00:00.000000', '2026-02-10 17:00:00.000000', '自行车停放区更新',         '涉及车棚附近的日常帮助任务，建议注明具体车位编号。', b'0', 1),
  (11, '2026-02-11 18:00:00.000000', '2026-02-11 18:00:00.000000', '医务帮助建议',         '代取药品或陪同就诊类任务，请提前写明联系方式和时间安排。', b'0', 1),
  (12, '2026-02-12 19:00:00.000000', '2026-02-12 19:00:00.000000', '考试周互助建议',                '学习辅导类紧急任务建议写明课程名称、知识点和截止时间。', b'0', 1);
