  (2009, '2026-03-01 12:20:00.000000', '2026-03-01 12:50:00.000000', 1005, 10, '我午饭后能过去排队，打印完也可以拍照确认。',                                'REJECTED', '2026-03-01 12:50:00.000000'),
  (2010, '2026-03-01 12:30:00.000000', '2026-03-01 12:30:00.000000', 1005, 11, '我就在服务中心附近，下午4点前能帮你处理完。',                                                'PENDING',  NULL),
  (2011, '2026-03-01 13:20:00.000000', '2026-03-01 13:20:00.000000', 1006, 12, '我熟悉设计楼路线，也可以帮你一起搬箱子。',                                   'PENDING',  NULL),
  (2012, '2026-03-01 13:45:00.000000', '2026-03-01 13:45:00.000000', 1006, 13, '我有小推车，可以一次性把东西都运过去。',                                                 'PENDING',  NULL),
  (2013, '2026-03-01 14:20:00.000000', '2026-03-01 14:20:00.000000', 1007, 14, '我对生物基础部分比较熟，可以帮你梳理重点。',                                           'PENDING',  NULL),
  (2014, '2026-03-01 14:30:00.000000', '2026-03-01 14:30:00.000000', 1007, 15, '遗传学部分我比较熟，也可以帮你做题。',                                                     'PENDING',  NULL),
  (2015, '2026-03-01 15:20:00.000000', '2026-03-01 15:20:00.000000', 1008, 16, '我历史课下课后正好有空，可以帮忙搬。',                                                      'PENDING',  NULL),
  (2016, '2026-03-01 15:35:00.000000', '2026-03-01 15:35:00.000000', 1008, 17, '我住8号宿舍附近，这个任务我一趟就能完成。',                                               'PENDING',  NULL),
  (2017, '2026-03-02 09:20:00.000000', '2026-03-02 10:00:00.000000', 1009, 11, '我经常帮人优化展示文稿，今天可以处理。',                                           'ACCEPTED', '2026-03-02 10:00:00.000000'),
  (2018, '2026-03-02 09:35:00.000000', '2026-03-02 10:00:00.000000', 1009, 8,  '如果需要，我也可以帮你调整配色和图片布局。',                                                            'REJECTED', '2026-03-02 10:00:00.000000'),
  (2019, '2026-03-02 10:15:00.000000', '2026-03-02 10:50:00.000000', 1010, 14, '我下课会经过药房，可以很快帮你买到。',                                      'ACCEPTED', '2026-03-02 10:50:00.000000'),
  (2020, '2026-03-02 10:25:00.000000', '2026-03-02 10:50:00.000000', 1010, 2,  '如果取药时间在晚上6点后，我也可以帮忙。',                                                       'REJECTED', '2026-03-02 10:50:00.000000'),
  (2021, '2026-03-02 11:15:00.000000', '2026-03-02 11:50:00.000000', 1011, 15, '我做过活动海报，今晚可以帮你完善初稿。',                                  'ACCEPTED', '2026-03-02 11:50:00.000000'),
  (2022, '2026-03-02 11:25:00.000000', '2026-03-02 11:50:00.000000', 1011, 3,  '我可以帮你顺一遍文案结构和标题措辞。',                                              'REJECTED', '2026-03-02 11:50:00.000000'),
  (2023, '2026-03-02 12:15:00.000000', '2026-03-02 12:45:00.000000', 1012, 18, '我熟悉社团教室储物位置，可以安全取回脚架。',                           'ACCEPTED', '2026-03-02 12:45:00.000000'),
  (2024, '2026-03-02 12:25:00.000000', '2026-03-02 12:45:00.000000', 1012, 4,  '如果时间合适，我下课后也能过去拿设备。',                                               'REJECTED', '2026-03-02 12:45:00.000000'),
  (2025, '2026-03-02 13:15:00.000000', '2026-03-02 13:40:00.000000', 1013, 6,  '我参加过迎新值班，流程比较熟悉。',                               'ACCEPTED', '2026-03-02 13:40:00.000000'),
  (2026, '2026-03-02 13:25:00.000000', '2026-03-02 13:40:00.000000', 1013, 10, '如果还缺人，我也可以帮忙做来宾引导。',                                                    'REJECTED', '2026-03-02 13:40:00.000000'),
  (2027, '2026-03-02 14:20:00.000000', '2026-03-02 14:55:00.000000', 1014, 7,  '我擅长做纪要和总结，可以整理得比较清楚。',                                'ACCEPTED', '2026-03-02 14:55:00.000000'),
  (2028, '2026-03-02 14:30:00.000000', '2026-03-02 14:55:00.000000', 1014, 16, '如果晚一点需要，我也可以在档案室结束后过去。',                                                          'REJECTED', '2026-03-02 14:55:00.000000'),
  (2029, '2026-03-03 10:15:00.000000', '2026-03-03 10:40:00.000000', 1015, 9,  '我中午前能帮你把书和资料盒都整理好。',                                     'ACCEPTED', '2026-03-03 10:40:00.000000'),
  (2030, '2026-03-03 10:25:00.000000', '2026-03-03 10:40:00.000000', 1015, 5,  '如果需要第二个人一起搬，我也可以过去。',                                                      'REJECTED', '2026-03-03 10:40:00.000000'),
  (2031, '2026-03-03 11:15:00.000000', '2026-03-03 11:35:00.000000', 1016, 12, '我可以帮你卡时间，也能提一些展示建议。',                                       'ACCEPTED', '2026-03-03 11:35:00.000000'),
  (2032, '2026-03-03 11:20:00.000000', '2026-03-03 11:35:00.000000', 1016, 7,  '如果需要，我还可以帮你理一下表达逻辑。',                                              'REJECTED', '2026-03-03 11:35:00.000000'),
  (2033, '2026-03-03 12:10:00.000000', '2026-03-03 12:40:00.000000', 1017, 13, '我有拍摄经验，可以帮你控机位和节奏。',                                           'ACCEPTED', '2026-03-03 12:40:00.000000'),
  (2034, '2026-03-03 12:25:00.000000', '2026-03-03 12:40:00.000000', 1017, 3,  '我可以协助列镜头清单，也能帮忙备份录制。',                                             'REJECTED', '2026-03-03 12:40:00.000000'),
  (2035, '2026-03-03 13:20:00.000000', '2026-03-03 13:50:00.000000', 1018, 4,  '我可以陪你练习辩论表达和发音。',                                        'ACCEPTED', '2026-03-03 13:50:00.000000'),
  (2036, '2026-03-03 13:35:00.000000', '2026-03-03 13:50:00.000000', 1018, 14, '今晚如果需要，我可以帮你梳理论证结构。',                                              'REJECTED', '2026-03-03 13:50:00.000000'),
  (2037, '2026-02-15 09:15:00.000000', '2026-02-15 09:45:00.000000', 1019, 10, '我中午有空，可以把午餐直接送到工作坊教室。',                           'ACCEPTED', '2026-02-15 09:45:00.000000'),
  (2038, '2026-02-15 09:20:00.000000', '2026-02-15 09:45:00.000000', 1019, 6,  '如果时间在中午12点左右，我也能帮忙。',                                           'REJECTED', '2026-02-15 09:45:00.000000'),
  (2039, '2026-02-17 10:20:00.000000', '2026-02-17 10:50:00.000000', 1020, 17, '我之前在这栋楼搬过桌椅，路线比较熟。',                           'ACCEPTED', '2026-02-17 10:50:00.000000'),
  (2040, '2026-02-17 10:30:00.000000', '2026-02-17 10:50:00.000000', 1020, 11, '如果你还需要备选人手，我软件课后可以过去。',                                                 'REJECTED', '2026-02-17 10:50:00.000000'),
  (2041, '2026-02-20 11:20:00.000000', '2026-02-20 12:00:00.000000', 1021, 5,  '我可以先帮你整理讨论提纲，再一起参与讨论。',                                     'ACCEPTED', '2026-02-20 12:00:00.000000'),
  (2042, '2026-02-20 11:35:00.000000', '2026-02-20 12:00:00.000000', 1021, 8,  '如果还需要人，我也愿意一起参与案例讨论。',                                 'REJECTED', '2026-02-20 12:00:00.000000'),
  (2043, '2026-02-22 12:15:00.000000', '2026-02-22 12:45:00.000000', 1022, 2,  '我下午4点前可以把画材送到工作室。',                           'ACCEPTED', '2026-02-22 12:45:00.000000'),
  (2044, '2026-02-22 12:25:00.000000', '2026-02-22 12:45:00.000000', 1022, 9,  '如果还没找到人，我也能帮忙一起搬运。',                                          'REJECTED', '2026-02-22 12:45:00.000000'),
  (2045, '2026-03-04 14:20:00.000000', '2026-03-04 14:45:00.000000', 1023, 14, '原本我可以接这单，不过任务已经取消了。',                           'CANCELLED','2026-03-04 14:45:00.000000'),
  (2046, '2026-03-04 14:30:00.000000', '2026-03-04 14:45:00.000000', 1023, 18, '如果之后恢复发布，我还可以继续帮忙。',                                             'REJECTED', '2026-03-04 14:45:00.000000'),
  (2047, '2026-03-04 15:20:00.000000', '2026-03-04 15:50:00.000000', 1024, 3,  '如果任务没取消，我下课后就能去领资料。',                                                  'CANCELLED','2026-03-04 15:50:00.000000'),
  (2048, '2026-03-04 15:35:00.000000', '2026-03-04 15:50:00.000000', 1024, 10, '如果之后重新发布，我可以顺路送到教室。',                                         'REJECTED', '2026-03-04 15:50:00.000000');
