  (3006, '2026-02-21 17:18:00.000000', '2026-02-21 17:18:00.000000', 1021, 5,  15, 4, '发布人沟通专业，配合起来很轻松。'),
  (3007, '2026-02-23 18:40:00.000000', '2026-02-23 18:40:00.000000', 1022, 18, 2,  5, '画材送达安全，而且比预期更早。'),
  (3008, '2026-02-23 18:50:00.000000', '2026-02-23 18:50:00.000000', 1022, 2,  18, 5, '沟通清楚，确认完成也很及时。');
